'use strict';
(function(root){
const R=CombatRules,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='walk-agiro-practical-v1';
function defaults(){return {version:1,speeds:[1450,1433,1184,985],mp:[700,900,800,600],variant:'reference',preparation:'eradicate',support:'support',echo:true,hp:1300000,maxHP:2400000,guardTurns:4,criticalActions:1,proficiency:true,unlock:true,damage:{},attested:false};}
function validate(x){const d=defaults();if(!x||x.version!==1)return d;if(!['user','article','reference'].includes(x.variant)||!['eradicate','insight'].includes(x.preparation))throw Error('保存条件が不正です。');for(const [k,min,max]of [['hp',1,100000000],['maxHP',1,100000000],['guardTurns',1,20],['criticalActions',0,10]])if(!Number.isInteger(x[k])||x[k]<min||x[k]>max)throw Error('保存条件が不正です。');for(const k of ['speeds','mp'])if(!Array.isArray(x[k])||x[k].length!==4||x[k].some(v=>!Number.isInteger(v)||v<0||v>100000))throw Error('保存能力が不正です。');if(x.hp>x.maxHP)throw Error('残HPが最大HPを超えています。');for(const v of Object.values(x.damage||{}))if(v!==null&&(!Number.isInteger(v)||v<0||v>100000000))throw Error('ダメージ値が不正です。');if(!['support','rondo','defend'].includes(x.support||'support'))throw Error('補助条件が不正です。');return {...d,...x,support:x.support||'support',damage:{...x.damage}};}
function read(){try{return validate(JSON.parse(localStorage.getItem(key)));}catch{return defaults();}}
function run(master,profile,cfg){
 const t=R.template(master,profile,cfg.variant),script=R.script(cfg.variant,cfg.preparation,cfg.support);const mapping=t.assignment||[0,1,2,3];
 const actors=t.loadouts.map((l,i)=>{l={...l,proficiency:cfg.proficiency,unlocks:cfg.unlock?(i===3?[cfg.preparation==='insight'?'超人道4':'超魔道4']:l.unlocks):[]};return {job:l.job,unlocks:l.unlocks,available:R.resolve(master,l).skills.map(s=>s.id),mp:cfg.mp[i],criticalActions:i===3?cfg.criticalActions:0,extensionUntil:cfg.variant==='reference'&&i===3?3:0,partner:cfg.variant==='reference'&&i===2?3:undefined,isProtagonist:mapping[i]===0};});
 script.filter(s=>s.effects).forEach(s=>s.effects.forEach(e=>e.remaining=cfg.guardTurns));
 const result=R.simulate({actors,hp:cfg.hp,thresholds:[.1,.2,.3,.5].map(v=>Math.round(cfg.maxHP*v)),script,echo:cfg.echo,damage:(s,a,enemy,cast)=>{const v=cfg.damage[script.indexOf(s)+'-'+cast];return v===null||v===undefined?NaN:v;}});
 return {...result,template:t,mapping,script,speed:R.speedCheck(cfg.speeds,1.2,cfg.variant==='reference'?[[0,2],[1,2],[2,3]]:undefined),attested:cfg.attested,eligible:t.issues.length===0};
}
function render({target,master,profile}){
 let cfg=read();const t=R.template(master,profile,cfg.variant);
 target.innerHTML=`<div class="row spread"><h2>アギロゴス 実戦検証</h2><span class="badge pending">ルール対応 0.5</span></div><p>いただいた構成を基準に、所持数と職業レベルから担当を割り当て、手順の成立条件を検証します。通常の概算探索とは別に保存します。</p><div class="notice">装備・こころの完全な火力最適化は整備中です。この画面は実戦例の必須装備を選定し、取得元・回数・MP・追加行動・シールドを確認します。防具・こころ4枠の全自動確定と耐久保証はまだ行いません。</div><form id="practical-form"><div class="details-grid"><section class="panel"><h3>手順の条件</h3><label>再現する攻略手順<select name="variant"><option value="reference" ${cfg.variant==='reference'?'selected':''}>記事の画像どおり（装備・並び・操作）</option><option value="user" ${cfg.variant==='user'?'selected':''}>当初の文章の手順（魔人へアンコール）</option><option value="article" ${cfg.variant==='article'?'selected':''}>当初説明＋大魔道士へアンコール</option></select></label><p class="notice">記事の画像では、大神官が月輪＋ケキ継承、守り人がラッキーフォーチュン、魔人の左手がロトのつるぎ改3です。記事再現では1Tバイシオン・ロンド・勇者の軌跡→根絶やし、2Tおうえん・時荒らし・大魔道士へアンコールを固定します。</p><div ${cfg.variant==='reference'?'hidden':''}><label>1ターン目・魔人の追加行動<select name="preparation"><option value="eradicate" ${cfg.preparation==='eradicate'?'selected':''}>根絶やし → 全身全霊斬り</option><option value="insight" ${cfg.preparation==='insight'?'selected':''}>会心のひらめき</option></select></label><label>2ターン目・守り人の補助<select name="support"><option value="support" ${cfg.support==='support'?'selected':''}>未指定（補助効果を加算しない）</option><option value="rondo" ${cfg.support==='rondo'?'selected':''}>風斬りのロンド（継承ケキちゃん）</option><option value="defend" ${cfg.support==='defend'?'selected':''}>ぼうぎょ（補助なし）</option></select></label><p class="muted"></div>根絶やしは攻撃スキルの選択までを1行動として計算。超魔道4と超人道4を併用しません。</p><label><input name="unlock" type="checkbox" ${cfg.unlock?'checked':''}> 必要なこころ道を解放済み</label><label><input name="proficiency" type="checkbox" ${cfg.proficiency?'checked':''}> ブーメラン錬度1以上（継承可能）</label><label><input name="echo" type="checkbox" ${cfg.echo?'checked':''}> 大魔道士のSHT継続で確定やまびこ</label><p class="muted">割合MPは端数切り上げで保守的に計算します。ロトの竜剣の対ドラゴン開幕SHTを前提にします。敵のテンション低下で失った場合は外してください。通常ざざん波を時荒らしに代用しません。</p></section><section class="panel"><h3>敵と効果</h3>${number('hp','開始時の残HP（おたすけ後・要確認）',cfg.hp,1,100000000)}${number('maxHP','敵最大HP（シールド基準）',cfg.maxHP,1,100000000)}${number('guardTurns','聖なる防壁の残りターン（仮・実測で修正）',cfg.guardTurns,1,20)}${number('criticalActions','魔人の確定会心の残り個人行動数（仮定）',cfg.criticalActions,0,10)}<p class="muted">記事再現ではラッキーフォーチュンを魔人の右隣に置き、3ターンの行動開始時延長を処理します。その他の手順では既定の確定会心は1行動。アンコールも個人行動を進めます。2ターン目まで自動継続としません。延長等を使う場合は実測に合わせて変更してください。</p><p>シールド基準：最大HPの10% / 20% / 30% / 50%。1回の攻撃前のシールド上限でHPダメージを制限し、破壊枚数は制限前のダメージで判定します。</p></section></div><h3 class="padded">実戦例の構成と担当</h3><p>パーティの並び：${t.positions.map(i=>R.roles[i].name).join(' → ')}。${cfg.variant==='reference'?'月輪の右隣と、ラッキーフォーチュンの左隣を魔人にします。':'行動順とは別の条件です。'}</p><div class="character-grid">${t.roles.map((r,i)=>{const l=t.loadouts[i],char=t.assignment?.[i];return `<section class="loadout"><h3>${r.name}</h3><p>${char===undefined?'育成条件不足':esc(profile.characters[char].name)+' / Lv.'+profile.characters[char].levels[r.job]}</p><p>${esc(l.items[0]?.name||r.weapon||'武器自由')}${l.left?' / 左手 '+esc(l.left.name):''}${l.inherit?' ＋ 継承 '+esc(l.inherit.name):r.inherit?' / 継承元不足':''}</p>${r.heart?'<p>必須こころ：是空天ミカヅチ（覚醒）</p>':''}${i===3?'<p>所持品から選定：'+esc(l.hearts.map(h=>h.name).join('、')||'特効こころなし')+' / '+esc(l.pearls?.map(h=>h.name+'S').join('、')||'特効心珠なし')+'</p>':''}${number('speed'+i,'すばやさ（実戦例の値・変更可）',cfg.speeds[i],0,100000)}${number('mp'+i,'最大MP（仮値・開幕消費は未反映）',cfg.mp[i],0,100000)}</section>`;}).join('')}</div><details class="panel sub"><summary>攻撃ごとのダメージを実測値で検証</summary><p>火力の完全な式が整うまでは、ダメージ不明のまま討伐成功にはしません。各着弾のシールド制限前ダメージを入力するとHPとブレイクを再計算します。時荒らしは各着弾の後に効果を短縮するため、1発目と2発目を別に入力してください。表示されたHPダメージが上限で切られた場合、その値だけでは制限前の火力を確定できません。</p><div id="damage-fields"></div><label><input name="attested" type="checkbox" ${cfg.attested?'checked':''}> 同じ装備・補助・属性・会心状態の実測値として確認した</label><p class="muted">入力値を固定した手順検証です。乱数下限や生存を保証するものではありません。装備や手順を変えた場合は測定値を見直してください。</p></details><div class="row padded"><button class="primary" type="submit">所持条件と操作手順を検証</button><button type="button" id="practical-export">検証条件をJSONで保存</button></div><p id="practical-save" role="status"></p></form><section id="practical-result"></section><details class="panel sub"><summary>確認したスキルと参照元</summary><ul class="source-list">${R.skills.filter(s=>s.id!=='support').map(s=>`<li><strong>${esc(s.name)}</strong>：${s.unlock?esc(s.unlock)+' / ':''}${s.mpRate?'最大MP '+s.mpRate*100+'%＋':''}${s.mp||0}MP${s.maxUses?' / '+s.maxUses+'回まで':''} · <a href="${s.source}" target="_blank" rel="noreferrer">出典</a></li>`).join('')}</ul><p><a href="${R.sources.official}" target="_blank" rel="noreferrer">公式：ぶき継承・シールド仕様</a> / <a href="${R.sources.example}" target="_blank" rel="noreferrer">元の攻略記事</a></p></details>`;
 const form=target.querySelector('#practical-form'),fields=target.querySelector('#damage-fields'),out=target.querySelector('#practical-result'),status=target.querySelector('#practical-save');
 function drawFields(){const s=R.script(cfg.variant,cfg.preparation,cfg.support);fields.innerHTML=s.flatMap((a,i)=>{if(R.skill(a.skill)?.kind!=='damage')return [];return Array.from({length:a.skill==='timewave'&&cfg.echo?2:1},(_,cast)=>`<label>${a.turn}T ${R.roles[a.actor].name} ${esc(R.skill(a.skill).name)}${a.skill==='timewave'?' '+(cast+1)+'発目':''}<input type="number" min="0" max="100000000" step="1" name="d${i}-${cast}" value="${cfg.damage[i+'-'+cast]??''}" placeholder="未確定"></label>`);}).join('');}
 function collect(){const fd=new FormData(form);const changed=['variant','preparation','support'].some(k=>cfg[k]!==fd.get(k))||cfg.echo!==fd.has('echo');let next={...cfg};for(const k of ['variant','preparation','support'])next[k]=fd.get(k)||cfg[k];for(const k of ['unlock','proficiency','echo','attested'])next[k]=fd.has(k);for(const k of ['hp','maxHP','guardTurns','criticalActions'])next[k]=Number(fd.get(k));next.speeds=R.roles.map((_,i)=>Number(fd.get('speed'+i)));next.mp=R.roles.map((_,i)=>Number(fd.get('mp'+i)));next.damage={};if(!changed)for(const [k,v]of fd)if(k.startsWith('d')&&/^d\d+-\d+$/.test(k))next.damage[k.slice(1)]=v===''?null:Number(v);if(changed)next.attested=false;return validate(next);}
 function show(){const r=run(master,profile,cfg);const problems=[...r.template.issues,...r.issues];const order=r.speed.every(s=>s.nominal);out.innerHTML=`<article class="panel sub"><h2>${problems.length?'手順・所持条件に不足':!r.known?'ダメージ未確定・討伐判定を保留':r.killed?'入力ダメージ条件では討伐':'入力ダメージ条件では未討伐'}</h2><p>${r.eligible?'必須装備と4職の割り当てが可能。':'必須条件に不足があります。'} 防具・こころ全枠の自動最適化と耐久は未検証です。</p>${problems.length?'<ul class="errorlist">'+problems.map(p=>'<li>'+esc(p)+'</li>').join('')+'</ul>':''}<div class="row"><span class="pill">HP反映済みダメージ ${r.damage.toLocaleString()}</span><span class="pill">入力済み部分の残HP ${r.enemy.hp.toLocaleString()}</span><span class="pill">確認できたブレイク ${r.enemy.broken} / 4枚</span></div>${r.unknown.length?'<p class="notice">未入力・未指定の攻撃があるため、上記は入力済み部分のみです。</p>':''}<h3>行動順の検査</h3><p>${order?'基準値の大小は指定順です。':'基準値の大小が指定順になっていません。'} 実戦例の成功と、乱数を含む保証は分けて表示します。記事再現では守り人と大魔道士の相互順は必須とせず、両者→大神官→魔人を検査します。速度範囲1〜1.2倍を仮定した味方間の判定：</p><ul>${r.speed.map(s=>`<li>${R.roles[s.first].name} → ${R.roles[s.second].name}：${s.certain?'仮定した範囲で順序成立':'範囲が重なり保証できない'}（前者 ${cfg.speeds[s.first]} / 後者 ${cfg.speeds[s.second]}、十分条件は前者${s.required}以上）</li>`).join('')}</ul><p class="muted">敵の割り込み・月輪のいきなり速度補助・途中の速度変化は未検証。下記は指定順が実現した場合の再生です。パーティの並び順は行動順と別です。記事再現では大神官の右隣、守り人の左隣が魔人です。</p><h3>取得元を確認した操作手順</h3><ol class="timeline">${r.steps.map(s=>`<li><strong>${s.turn}T ${s.actor==='enemy'?'アギロゴス':R.roles[s.actor].name} → ${esc(R.skill(s.skill)?.name||s.skill)}</strong><br>${esc(s.detail)}${s.hit?'<br>制限前 '+s.hit.raw.toLocaleString()+' / HP反映 '+s.hit.applied.toLocaleString()+' / 破壊 '+s.hit.broken+'枚':''}<br><span class="muted">残HP ${s.hp.toLocaleString()} / 効果：${s.effects.map(e=>esc(e.name)+' 残り'+e.remaining).join('、')||'登録効果なし'}</span></li>`).join('')}</ol><p>操作分を引いた残りMP（開幕消費は未反映）：${r.actors.map((a,i)=>R.roles[i].name+' '+a.mp).join(' / ')}</p><p class="muted">聖なる防壁を敵の1T終了時に置くのは、この実戦例の再生条件です。敵の行動分岐・被ダメージ・におうだち時の耐久・領域競合・二刀流の追加ダメージ・レインボーフォースの属性別火力は実測確認が残ります。${cfg.attested?'入力ダメージは実測として記録済み。':'入力ダメージの実測確認は未チェック。'}</p></article>`;}
 drawFields();show();form.onchange=e=>{if(!e.target.name.startsWith('d')&&e.target.name!=='attested'){cfg.damage={};cfg.attested=false;drawFields();form.elements.attested.checked=false;}out.innerHTML='<p class="notice">条件が変わりました。検証を実行してください。</p>';};
 for(const name of ['variant','preparation','support','echo'])form.elements[name].onchange=()=>{cfg=collect();if(name==='variant'){localStorage.setItem(key,JSON.stringify(cfg));render({target,master,profile});return;}drawFields();out.innerHTML='<p class="notice">手順変更によりダメージ入力をクリアしました。再検証してください。</p>';};
 form.onsubmit=e=>{e.preventDefault();try{cfg=collect();localStorage.setItem(key,JSON.stringify(cfg));status.textContent='検証条件を保存しました。';show();}catch(err){status.textContent=err.message;}};
 target.querySelector('#practical-export').onclick=()=>{try{const data=collect(),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='agiro-validation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){status.textContent=e.message;}};
}
function number(name,label,value,min,max){return `<label>${label}<input type="number" name="${name}" value="${value}" min="${min}" max="${max}" step="1" required></label>`;}
root.AgiroUI={render,defaults,validate,run};
})(typeof window==='undefined'?globalThis:window);
